import { isEqual } from 'lodash-es';
import { useState, useMemo } from 'react';
import { TableDispatch } from 'react-table';

import { useColumnsSizesActions } from '../plugins/use-column-sizes/actions.js';
import { ColumnMinInstance } from '../types/internal-table-types.js';

/**
 * If the columns in the column definition changed, we need to update the columnResizing.columnWidths object,
 * in case columns were removed
 *
 * @param columns - ordered columns without affix columns
 * @param dispatch - table dispatch fn
 */
export function useUpdateResizedColumnWidths(
  columns: ColumnMinInstance[],
  dispatch: TableDispatch,
) {
  const allOrderingColumnIds = useMemo(
    () => columns.map((column) => column.id),
    [columns],
  );

  const [prevAllOrderingColumnIds, setPrevAllOrderingColumnIds] =
    useState<string[]>(allOrderingColumnIds);

  if (!isEqual(prevAllOrderingColumnIds, allOrderingColumnIds)) {
    dispatch({
      type: useColumnsSizesActions.updateResizedColumnWidths,
      currentColumnIds: allOrderingColumnIds,
    });
    setPrevAllOrderingColumnIds(allOrderingColumnIds);
  }
}
